interface Merged {
  contexts: string[];
  messages: string[];
  blockReasons: string[];
  stop?: HookResult;
  updatedToolOutput?: unknown;
  updatedMCPToolOutput?: unknown;
}

function absorb(m: Merged, r: HookResult | undefined, member: PosttoolMember): void {
  if (!r) return;
  const hso: HookSpecificOutput | undefined = r.hookSpecificOutput;
  if (hso?.additionalContext) m.contexts.push(hso.additionalContext);
  if (r.systemMessage) m.messages.push(r.systemMessage);
  if (member.rewake) {
    // run-hook.mjs --rewake: a stop exits 2 with the stopReason, and CC
    // wakes Claude with it. Here it becomes a block reason Claude sees now.
    if (r.continue === false) m.blockReasons.push(r.stopReason ?? r.reason ?? `${member.id} stopped`);
    return;
  }
  if (member.async) return;
  if (r.continue === false && !m.stop) m.stop = r;
  if (r.decision === 'block') m.blockReasons.push(r.reason ?? r.stopReason ?? 'blocked');
  if (hso?.updatedToolOutput !== undefined && m.updatedToolOutput === undefined) m.updatedToolOutput = hso.updatedToolOutput;
  if (hso?.updatedMCPToolOutput !== undefined && m.updatedMCPToolOutput === undefined) {
    m.updatedMCPToolOutput = hso.updatedMCPToolOutput;
  }
}

function build(m: Merged): HookResult {
  const hso: HookSpecificOutput = { hookEventName: 'PostToolUse' };
  let hasHso = false;
  if (m.contexts.length) {
    hso.additionalContext = m.contexts.join('\n\n---\n\n');
    hasHso = true;
  }
  if (m.updatedToolOutput !== undefined) {
    hso.updatedToolOutput = m.updatedToolOutput;
    hasHso = true;
  }
  if (m.updatedMCPToolOutput !== undefined) {
    hso.updatedMCPToolOutput = m.updatedMCPToolOutput;
    hasHso = true;
  }
  const result: HookResult = m.stop
    ? { ...m.stop }
    : { continue: true, suppressOutput: !hasHso && m.messages.length === 0 && m.blockReasons.length === 0 };
  if (hasHso) result.hookSpecificOutput = hso;
  if (m.messages.length) result.systemMessage = m.messages.join('\n');
  if (m.blockReasons.length) {
    result.decision = 'block';
    result.reason = m.blockReasons.join('\n');
  }
  return result;
}

/**
 * Run every handler the matching groups name, each id once: guards first,
 * then observers, each in file order and within its own budget.
 * `handlers` and `groups` are injectable for tests.
 */
export async function posttoolDispatch(
  input: HookInput,
  ctx: HookContext = NOOP_CTX,
  handlers: Record<string, Fn> = POSTTOOL_HANDLERS,
  groups: PosttoolGroup[] = POSTTOOL_GROUPS,
  env: ProofEnv = process.env,
): Promise<HookResult> {
  const tool = input.tool_name ?? '';
  const merged: Merged = { contexts: [], messages: [], blockReasons: [] };
  const proof = new ProofLog(env, 'PostToolUse', tool);
  // Every member the matching groups name, each id once, in file order; the
  // guards (sync, rewake) then run before every plain async observer.
  const seen = new Set<string>();
  const members: PosttoolMember[] = [];
  for (const group of groups) {
    if (!ccMatcherMatches(group.matcher, tool)) continue;
    for (const member of group.hooks) {
      if (seen.has(member.id)) continue;
      seen.add(member.id);
      members.push(member);
    }
  }
  const isGuard = (m: PosttoolMember) => !m.async || m.rewake === true;
  const ordered = [...members.filter(isGuard), ...members.filter((m) => !isGuard(m))];
  const deadline = Date.now() + RUN_BUDGET_MS;
  for (const member of ordered) {
    const { id } = member;
    const fn = handlers[id];
    if (!fn) {
      proof.record(id, 'failed');
      if (!isGuard(member)) {
        // Same as run-hook.mjs today: a missing observer is skipped.
        ctx.log(HOOK_NAME, `no handler for ${id} (skipped)`);
        continue;
      }
      // A handler whose verdict counts must not pass when its code is absent.
      ctx.log(HOOK_NAME, `no handler for ${id} (blocks)`);
      merged.blockReasons.push(
        `[orchestkit] hook "${id}" has no handler in this build, so it blocks. Rebuild (cd src/hooks && npm run build) or reinstall the plugin.`,
      );
      continue;
    }
    const budget = Math.min((member.timeout ?? 15) * 1000, deadline - Date.now());
    try {
      const r = await withBudget(() => {
        if (proofBreaks(env, id)) throw proofBreakError(id);
        return fn(input, ctx);
      }, budget);
      if (r === TIMED_OUT) {
        ctx.log(HOOK_NAME, `${id} over its ${budget} ms budget (abandoned)`);
        proof.record(id, 'failed');
        // A guard verdict lost to time fails closed; an observer stays silent.
        if (isGuard(member)) {
          merged.blockReasons.push(
            `[orchestkit] hook "${id}" did not finish within its ${budget} ms budget, so it blocks.`,
          );
        }
        continue;
      }
      absorb(merged, r, member);
      proof.record(id, 'ok');
    } catch (err) {
      ctx.log(HOOK_NAME, `${id} failed (isolated): ${err instanceof Error ? err.message : String(err)}`);
      proof.record(id, 'failed');
    }
  }
  const result = build(merged);
  const message = proof.appendTo(result.systemMessage);
  if (message !== undefined) result.systemMessage = message;
  return result;
}

/** Entry-map handler (registered as posttool/tool-dispatcher). */
export function posttoolToolDispatcher(input: HookInput, ctx: HookContext = NOOP_CTX): Promise<HookResult> {
  return posttoolDispatch(input, ctx);
}
